import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), m = nextInt();
        long[] a = new long[m];
        long lo = 0, hi = 0;
        for (int i = 0; i < m; i++) {
            a[i] = nextLong();
            lo = Math.max(lo, a[i]);
            hi += a[i];
        }
        // Binary search the smallest cap that needs at most n greedy segments.
        while (lo < hi) {
            long mid = (lo + hi) / 2, load = 0;
            int parts = 1;
            for (long x : a) {
                if (load + x > mid) {
                    parts++;
                    load = x;
                } else load += x;
            }
            if (parts <= n) hi = mid;
            else lo = mid + 1;
        }
        System.out.println(lo);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := int(nextInt()), int(nextInt())
	a := make([]int64, m)
	var lo, hi int64
	for i := range a {
		a[i] = nextInt()
		lo = max(lo, a[i])
		hi += a[i]
	}
	// Binary search the smallest cap that needs at most n greedy segments.
	for lo < hi {
		mid := (lo + hi) / 2
		var load int64
		parts := 1
		for _, x := range a {
			if load+x > mid {
				parts++
				load = x
			} else {
				load += x
			}
		}
		if parts <= n {
			hi = mid
		} else {
			lo = mid + 1
		}
	}
	fmt.Println(lo)
}
